// shows the count of words of the text the user typed in the tab
export function mount(root) {
  const box = document.createElement('textarea');
  const out = document.createElement('p');
  box.oninput = () => { out.textContent = String(box.value.split(/\s+/).filter(Boolean).length) + ' words'; };
  root.append(box, out);
}
